{
  "candidate_edge_types": [
    {
      "name": "ATTEMPTS_TO_REPAIR",
      "definition": "A subsequent agent action modifies the code or environment in an attempt to resolve a failure, error, or incompatibility identified in an earlier execution result.",
      "source_description": "An earlier observed execution failure or error result.",
      "target_description": "A subsequent agent action (edit, patch, or reinstall) intended to resolve that failure."
    },
    {
      "name": "INVESTIGATES_FAILURE_CAUSE",
      "definition": "A subsequent agent action gathers diagnostic information about an earlier failure, such as locating all occurrences of the problematic construct or inspecting related sources, in order to understand the scope or cause before fixing it.",
      "source_description": "An earlier observed execution failure or error result.",
      "target_description": "A subsequent diagnostic action that searches or inspects code to determine the cause or extent of the failure."
    },
    {
      "name": "VERIFIES_REPAIR_EFFECTIVENESS",
      "definition": "After a repair action has been applied, the agent re-executes the previously failing check to confirm that the failure is resolved and the repaired component now behaves correctly.",
      "source_description": "An applied repair action or fix that addresses an earlier failure.",
      "target_description": "A subsequent execution that re-runs the affected operation to confirm the repair succeeded."
    },
    {
      "name": "CONFIRMS_TASK_COMPLETION",
      "definition": "A successful final verification result, produced after all repairs, is used as the justification for declaring the task complete.",
      "source_description": "A verification execution whose result demonstrates the required functionality works.",
      "target_description": "An agent decision or action that marks the task as complete based on that verification result."
    }
  ]
}

